scintilla.text:
// headless Scintilla hosted in a SOUI SWindow.
// No native HWND is used to render or dispatch events.
int main()
{
    printf("hello world\n");
    for (int i = 0; i < 40; ++i)
    {
        printf("line %d: enough text to grow the vertical scrollbar.\n", i);
        if (i % 4 == 0)
        {
            printf("    - indented multi-line block %d\n", i);
            printf("    - another line in the block\n");
        }
    }
    return 0;
}
